+);
+/** Same wall, same physical width, re-authored in a millimetre-declared project. */
+export const UNIT_SCALE_MILLIMETRE_MODEL = unitScaledPropertyModel(
+  '#31= IFCSIUNIT(*,.LENGTHUNIT.,.MILLI.,.METRE.);',
+  '2500.',
+);
